function SAT(n, H):
  best <- +inf
  for each subset E of the (n choose 2) vertex pairs:
    G <- graph (n, E)
    if not CONTAINS_COPY(G, H):                # G is H-free
      saturated <- true
      for each nonedge e of G:
        if not CONTAINS_COPY(G + e, H):
          saturated <- false; break
      if saturated: best <- min(best, |E|)
  return best

function CONTAINS_COPY(G, H):
  for each injection f : V(H) -> V(G):
    if every edge uv of H maps to an edge f(u)f(v) of G: return true
  return false

